"""Chapter 4 (part B): 4.5 slip resistance (all BPN values are [Place Holder]), 4.6 market comparison and shape effect."""
from ch4_common import *

ALL = ["NA", "RA", "Rab5", "Rab10", "Rab15", "RCA0", "RCA5", "RCA10", "RCA15"]
NM = {"NA": "NA", "RA": "RA", "Rab5": "Rab5%", "Rab10": "Rab10%", "Rab15": "Rab15%", "RCA0": "RCA 0%", "RCA5": "RCA 5%", "RCA10": "RCA 10%", "RCA15": "RCA 15%"}


def ph(x):
    return f"<ph>{x}</ph>"


def build(b, N):
    B = N["bpn"].set_index(["mix", "age"])
    # ------------------------------------------------------------------ 4.5
    b.h2("4.5 ผลการทดสอบความต้านทานการลื่นไถล")
    b.p(f"{PH} ตัวเลข ตาราง และภาพทั้งหมดในหัวข้อ 4.5 เป็นค่าสมมติ ไม่ใช่ผลการวัด ณ วันที่จัดทำรายงาน การทดสอบความต้านทานการลื่นไถลยังไม่เสร็จสิ้น ผู้วิจัยจึงจัดทำชุดข้อมูลสมมติที่สอดคล้องกับกลศาสตร์ของวัสดุเพื่อแสดงรูปแบบการรายงาน วิธีวิเคราะห์ และเกณฑ์ตัดสิน ให้ทดแทนด้วยข้อมูลจริงได้ทันทีโดยไม่ต้องเปลี่ยนโครงสร้างของหัวข้อ ข้อสรุปใดในหัวข้อนี้ที่มาจากตัวเลขสมมติไม่ใช่ผลการวิจัยและห้ามอ้างอิงออกไปภายนอก", first=True)
    b.h3("4.5.1 วิธีการ และที่มาของค่าสมมติ")
    b.p(ot(349, {"ASTM E303-22": "ASTM E303-22 {c:astme303}", "หัวข้อที่ 3.5.4": "หัวข้อ 3.5.4"}))
    b.p("ร่างเดิมมีตารางผลความต้านทานการลื่นไถล (ตารางที่ 4-6 เดิม) ที่มีตัวเลขครบ 28 วันของ 8 สูตร ผู้วิจัยยืนยันว่าเป็นค่าตัวอย่างหรือค่าสมมติ จึงใช้เป็นจุดยึดที่อายุ 28 วัน และเติมสูตร NA ตามตรรกะเดียวกัน (สูตร NA ไม่อยู่ในตารางเดิม) ค่าที่อายุ 7 และ 14 วัน สร้างจากแบบจำลองที่ผู้วิจัยตั้งขึ้น ดังนี้")
    b.bullets(["ค่า BPN สภาวะแห้งที่อายุ t คำนวณจาก BPN<sub>dry</sub>(t) = BPN<sub>dry,28</sub> − 6.5 × (1 − f<sub>c</sub>(t)/f<sub>c,28</sub>) โดย f<sub>c</sub>(t)/f<sub>c,28</sub> คืออัตราส่วนกำลังอัดที่วัดได้จริงของสูตรเดียวกัน ({tab:rfc1} และ {tab:rfc2}) สัมประสิทธิ์ 6.5 เป็นสมมติฐานที่ปรับให้ค่าเปลี่ยนตามอายุในระดับที่รายงานตัวอย่างปี 2568 แสดง " + PH,
                "ค่า BPN สภาวะเปียกได้จากผลต่างแห้ง–เปียกที่ 28 วันของแต่ละสูตรในตารางเดิม บวกค่ารบกวนสุ่มขนาดเล็ก (SD ประมาณ 0.35 BPN)",
                "ส่วนเบี่ยงเบนมาตรฐานระหว่างก้อนสุ่มในช่วง 1.0–1.8 BPN (แห้ง) และ 1.2–2.2 BPN (เปียก) ซึ่งเป็นระดับความทำซ้ำที่เครื่องลูกตุ้มมักให้ ใช้เมล็ดสุ่มคงที่ (20690101) เพื่อให้ผลสร้างซ้ำได้",
                "ทุกสูตรทุกอายุมี 3 ก้อน ก้อนละ 3 สโตรก ตามวิธีในหัวข้อ 3.5.4"])
    b.p("ค่าสมมติจึงมีสมบัติที่ควรมีตามหลักกลศาสตร์ คือ เปียกต่ำกว่าแห้งทุกกรณี และสูตรที่กำลังอัดต่ำกว่าไม่มี BPN สูงกว่าแบบฉับพลัน แต่สหสัมพันธ์ใด ๆ ที่คำนวณจากค่าเหล่านี้เป็นผลของวิธีสร้างข้อมูล ไม่ใช่หลักฐานเชิงประจักษ์ ผู้วิจัยแสดงค่า R<sup>2</sup> ในภาพเพื่อสาธิตวิธีวิเคราะห์เท่านั้นและไม่รายงานค่า p")

    # table
    b.h3("4.5.2 ผลสมมติของ BPN สภาวะแห้งและเปียก")
    wmin, wmax, dmin, dmax = (ph(f"{N[k]:.1f}") for k in ("bpn_wet_min", "bpn_wet_max", "bpn_dry_min", "bpn_dry_max"))
    wdm, wd0, wd1 = (ph(f"{N[k]:.1f}") for k in ("wetdrop_mean", "wetdrop_min", "wetdrop_max"))
    b.p(f"{PH} {{tab:rbpn}} แสดงค่า BPN เฉลี่ยและ SD ของแต่ละสูตรที่อายุ 7 14 และ 28 วัน ทั้งสภาวะแห้งและเปียก ค่า BPN สภาวะเปียกอยู่ระหว่าง {wmin} ถึง {wmax} และสภาวะแห้งอยู่ระหว่าง {dmin} ถึง {dmax} ผลต่างแห้ง–เปียกเฉลี่ย {wdm} BPN (ช่วง {wd0}–{wd1})")
    hdr = [["สูตร", ("7 วัน", 2), ("14 วัน", 2), ("28 วัน", 2)], ["", "แห้ง", "เปียก", "แห้ง", "เปียก", "แห้ง", "เปียก"]]
    rows = []
    for m in ALL:
        row = [NM[m]]
        for age in (7, 14, 28):
            r = B.loc[(m, age)]
            row += [ph(f"{r.bpn_dry:.1f} ± {r.sd_dry:.1f}"), ph(f"{r.bpn_wet:.1f} ± {r.sd_wet:.1f}")]
        rows.append(row)
    b.table("rbpn", PH + " ค่า BPN (ค่าเฉลี่ย ± SD) ของคอนกรีตบล็อกปูพื้น ทุกอัตราส่วนผสมและอายุบ่ม", hdr, rows, [1350, 1300, 1300, 1300, 1300, 1300, 1300], sz=19, header_rows=2,
            note="หมายเหตุ ตัวเลขทั้งหมดเป็นค่าสมมติ " + PH + " ที่ 28 วัน ค่าของ 8 สูตรตรงกับค่าตัวอย่างในร่างเดิม (ที่ผู้วิจัยยืนยันว่าเป็นค่าสมมติ) ส่วนสูตร NA และค่าที่ 7 และ 14 วันสร้างตามหัวข้อ 4.5.1 n = 3 ก้อนต่อเซลล์")
    b.fig("rbpnbars", fp("r_bpn_bars"), 15.0, PH + " ค่า BPN ที่ 28 วัน สภาวะแห้งและเปียก ของทุกสูตร เส้นประคือเกณฑ์ 45 และ 60 BPN ที่ยังไม่ยืนยันแหล่งที่มา (ดูหัวข้อ 4.5.4) ผู้วิจัยสร้างภาพจากค่าสมมติใน{tab:rbpn}")
    b.p(f"{PH} ในชุดข้อมูลสมมตินี้ ค่าเปียกของทุกสูตรต่ำกว่าสภาวะแห้ง และสูตรที่มีถ่านชีวภาพมากขึ้นหรือ RCA มากขึ้นมีค่าลดลงเล็กน้อย การออกแบบเช่นนี้สอดคล้องกับสมมติฐาน H3 ของหัวข้อ 1.5 แต่เนื่องจากค่าถูกสร้างขึ้นให้เป็นเช่นนั้น จึงไม่ใช่การทดสอบสมมติฐาน เมื่อได้ข้อมูลจริง ผู้วิจัยจะวิเคราะห์ด้วย ANOVA และ Tukey HSD เช่นเดียวกับกำลังอัด")
    b.fig("rbpnage", fp("r_bpn_age"), 14.5, PH + " การเปลี่ยนแปลงของ BPN ตามอายุบ่ม (ก) ชุดที่ 1 (ข) ชุดที่ 2 เส้นทึบคือสภาวะแห้ง เส้นประคือสภาวะเปียก ผู้วิจัยสร้างภาพจากค่าสมมติใน{tab:rbpn}")

    b.h3("4.5.3 แนวทางการวิเคราะห์เมื่อได้ข้อมูลจริง")
    b.p("เมื่อมีผลวัดจริง การวิเคราะห์ควรทำใน 4 ขั้น ขั้นแรก เปรียบเทียบ BPN ระหว่างสูตรด้วย ANOVA และ Tukey HSD แยกสภาวะแห้งและเปียก ขั้นที่สอง ตรวจผลต่างแห้ง–เปียก เพื่อดูว่าสูตรใดเสียเสียดทานมากเมื่อมีฟิล์มน้ำ ขั้นที่สาม เทียบ BPN เปียกกับตัวแปรทางวัสดุ (กำลังอัด ความหนาแน่น ปริมาณไบโอชาร์ ปริมาณ RCA) เพื่อหาตัวแปรที่อธิบายเสียดทานได้ ขั้นที่สี่ จัดประเภทความเสี่ยงตามเกณฑ์ที่ยืนยันแล้ว ภาพที่ {fig:rbpncorr} และ {fig:rbpnrisk} แสดงรูปแบบของขั้นที่สามและสี่ด้วยค่าสมมติ")
    b.fig("rbpncorr", fp("r_bpn_corr"), 15.0, PH + " รูปแบบการวิเคราะห์ความสัมพันธ์ (ก) BPN เปียกเทียบ BPN แห้ง เส้นเทาคือผลต่าง 8 10 และ 12 BPN (ข) BPN เปียกเทียบกำลังอัด 28 วัน (ค) BPN เปียกเทียบความหนาแน่น 28 วัน ของชุดที่ 1 R<sup>2</sup> ที่แสดงมาจากค่าสมมติ ไม่มีความหมายเชิงหลักฐาน")
    b.fig("rbpnrisk", fp("r_bpn_risk"), 15.0, PH + " การจัดประเภทความเสี่ยงของพื้นผิวเปียกตามช่วง PTV ของแนวทาง UKSRG (เกณฑ์เชิงแนวทาง ไม่ใช่เกณฑ์ผลิตภัณฑ์) จุดวงกลมคือค่าแห้ง จุดสี่เหลี่ยมคือค่าเปียก แถบคือ ±1 SD ผู้วิจัยสร้างภาพจากค่าสมมติที่ 28 วัน")

    b.h3("4.5.4 เกณฑ์ที่ใช้ตัดสิน และสิ่งที่ต้องตรวจสอบ")
    b.p("เกณฑ์ BPN มีข้อมูลขัดกันในเอกสารที่ผู้วิจัยมี ร่างเดิมระบุ 60 BPN สำหรับ มอก. 2035-2565 และ EN 1338 รายงานตัวอย่างปี 2568 ระบุ 45 BPN ตาม EN 1338 ส่วนวรรณกรรมที่ตรวจสอบได้ระบุว่า EN 1338 {c:en1338} กำหนดวิธีทดสอบลูกตุ้มไว้ในภาคผนวก I เพื่อหาค่า USRV และผู้วิจัยไม่พบข้อความที่ยืนยันตัวเลขขั้นต่ำของเกณฑ์ใดเกณฑ์หนึ่งจากต้นฉบับ รายงานนี้จึงแสดงทั้ง 45 และ 60 BPN ในกราฟโดยกำกับว่า [to be verified] และไม่ใช้เป็นข้อสรุปผ่าน/ไม่ผ่านของสูตรใด")
    rows = [["สูง (high)", "0–24", "พื้นผิวเปียกที่ลื่นมาก ไม่เหมาะกับทางสาธารณะ"],
            ["ปานกลาง (moderate)", "25–35", "ใช้ได้ในบางงานที่ตรวจควบคุมการระบายน้ำ"],
            ["ต่ำ (low)", "≥ 36", "ความเสี่ยงต่ำตามแนวทาง UKSRG"]]
    b.table("rslipband", "ช่วงค่าแรงเสียดทานของลูกตุ้มในสภาวะเปียก (PTV) ตามแนวทาง UKSRG ที่ใช้เป็นกรอบประกอบ", ["ศักยภาพการลื่นไถล", "PTV เปียก", "ความหมายเชิงปฏิบัติ"], rows, [2300, 1500, 5100], align=["left", "center", "left"], sz=21,
            note="หมายเหตุ ช่วงตัวเลขนี้อ้างจากข้อความรองในเว็บของ UKSRG {c:uksrg2016} ผู้วิจัยยังไม่ได้ตรวจกับฉบับเต็มของแนวทาง จึงต้องยืนยันก่อนใช้ในรายงานเผยแพร่ " + PH + " PTV ของเครื่องลูกตุ้มและ BPN ใช้สเกลเดียวกันแต่เงื่อนไขสไลเดอร์ต่างกันตามมาตรฐาน")
    b.p("เกณฑ์ที่ใช้กับบล็อกปูพื้นต้องเลือกจากเอกสารที่ผลิตภัณฑ์อ้างอิงเท่านั้น (มอก. 2035-2565 หรือ EN 1338) ขณะที่แนวทางปฏิบัติของ UKSRG ซึ่งใช้กับพื้นผิวเดินเท้า จัดเป็นกรอบประเมินความเสี่ยงเสริมใน{tab:rslipband} สองเกณฑ์นี้ไม่ควรสับสนกัน")

    b.h3("4.5.5 การตีความเชิงกลศาสตร์")
    b.p("ค่า BPN วัดพลังงานที่สูญเสียเมื่อสไลเดอร์ยางเสียดสีผิวตลอดระยะสัมผัสคงที่ ตามหลักงาน–พลังงาน พลังงานที่สูญเสียเท่ากับแรงเสียดทานคูณระยะสัมผัส และแรงเสียดทานเท่ากับสัมประสิทธิ์เสียดทานคูณแรงตั้งฉากจากสปริงของเครื่อง ดังนั้น BPN จึงเป็นสัดส่วนกับสัมประสิทธิ์เสียดทาน μ ของคู่ยาง–ผิวคอนกรีตที่สภาวะการทดสอบ ผู้วิจัยไม่รายงานสูตรแปลง BPN เป็น μ เพราะสัดส่วนคงที่ขึ้นกับรายละเอียดเครื่องที่ต้องอ้างจากภาคผนวกการสอบเทียบของ ASTM E303 {c:astme303} [to be verified]")
    b.p("เสียดทานของยางบนผิวหยาบมีสองส่วนตามทฤษฎีของ Persson {c:persson2001} ส่วนแรกคือการยึดติดที่ผิวสัมผัส (adhesion) ซึ่งขึ้นกับพื้นที่สัมผัสจริงและสภาพสะอาดของผิว ส่วนที่สองคือการสูญเสียพลังงานภายในยางเมื่อถูกยอดความหยาบกด (hysteresis) ซึ่งขึ้นกับสเปกตรัมความหยาบของผิวและความเร็วการเลื่อน เมื่อมีฟิล์มน้ำ ส่วนการยึดติดลดลงมากเพราะน้ำคั่นระหว่างยางกับผิว จึงทำให้ BPN เปียกต่ำกว่าแห้ง Chang และคณะ {c:chang2001} ทบทวนกลไกเสียดทานที่ผิวสัมผัสและการกำหนดสภาวะทดสอบ ซึ่งชี้ว่าค่าที่วัดขึ้นกับสภาวะการทดสอบ ตามหลักกลศาสตร์ ผิวระดับ microtexture ที่เกิดจากเม็ดทรายแข็งเหลี่ยมคมยังคงรักษา hysteresis ระดับเล็กไว้แม้เปียก ส่วน macrotexture ช่วยระบายน้ำ (ข้อความส่วนนี้เป็นการอธิบายตามหลักกลศาสตร์ของผู้วิจัย) Gierasimiuk และคณะ {c:gierasimiuk2021} ใช้ BPN ร่วมกับความลึกเนื้อผิว (MPD) แยกอิทธิพลสองระดับนี้ในคอนกรีตพื้นถนน")
    b.p("เมื่อประยุกต์กับสูตรของงานนี้ ผู้วิจัยตั้งสมมติฐานทางกลศาสตร์สามข้อ ซึ่งต้องทดสอบด้วยข้อมูลจริง ข้อแรก การลดซีเมนต์ทำให้เพสต์รอบเม็ดทรายอ่อนลง ผิวบล็อกจึงสึกเร็วขึ้นและ microtexture ของเม็ดทรายโผล่ชัดขึ้น ซึ่งอาจเพิ่ม BPN ข้อสอง อนุภาคไบโอชาร์เป็นคาร์บอนอ่อนและเรียบเมื่อถูกขัดจึงอาจลดเสียดทานที่ผิวถ้ากระจุกตัวใกล้ผิว ข้อสาม RCA ที่เหลี่ยมมุมเพิ่ม microtexture แต่ถ้ามีมอร์ตาร์เดิมเกาะผิวมาก ผิวอาจสึกเร็ว (ข้อความส่วนนี้เป็นสมมติฐานของผู้วิจัย) ผลของ Yuan และคณะ {c:yuan2025} ที่พบว่าการฝังหินเกล็ดที่ผิวคอนกรีตเพิ่มความต้านทานการลื่นไถลสนับสนุนบทบาทของมวลรวมที่ผิวต่อ BPN แต่เป็นคนละวิธีผลิตกับบล็อกอัดแน่น")
    b.h3("4.5.6 รายการที่ต้องดำเนินการเมื่อแทนค่าจริง")
    b.numbered(["ทดสอบตามหัวข้อ 3.5.4 กับก้อนที่ผ่านการบ่มครบอายุ 7 14 และ 28 วัน ทั้งสภาวะแห้งและเปียก ก้อนละ 3 สโตรกตามหัวข้อ 3.5.4 หรือจำนวนที่มาตรฐานที่เลือกกำหนด",
                "บันทึกอุณหภูมิผิว ชนิดและสภาพสไลเดอร์ ระยะสัมผัส และผลสอบเทียบเครื่องก่อนทดสอบทุกครั้ง แล้วปรับค่าตามอุณหภูมิตามเอกสารมาตรฐานที่ใช้",
                "ยืนยันเกณฑ์ผ่าน/ไม่ผ่าน (45 หรือ 60 BPN หรือค่าอื่น) จากต้นฉบับของ มอก. 2035-2565 และ EN 1338 แล้วแก้ข้อความใน{tab:std} และภาพที่ {fig:rbpnbars}",
                "แทนที่ {tab:rbpn} และภาพที่ {fig:rbpnbars} ถึง {fig:rbpnrisk} ด้วยค่าจริง ลบเครื่องหมาย [Place Holder] และแก้ข้อความหัวข้อ 4.5.2 ให้ตรงกับผล",
                "ถ้าผลจริงต่างจากสมมติฐาน H3 ให้ปรับข้อความในหัวข้อ 4.5.5 และ 5.1 ตามผลจริง ไม่ปรับผลให้ตรงกับสมมติฐาน"])

    # ------------------------------------------------------------------ 4.6
    b.h2("4.6 การเปรียบเทียบกับผลิตภัณฑ์ท้องตลาดและอิทธิพลของรูปทรงชิ้นทดสอบ")
    b.h3("4.6.1 การเปรียบเทียบกับผลิตภัณฑ์คอนกรีตบล็อกปูพื้นในท้องตลาด")
    b.p(ot(356, {"ตารางที่ 4-7 และภาพที่ 4-7": "{tab:rmkt} และ{fig:rmkt}"}))
    mk = pd.read_csv(os.path.join(DATA, "market_table4-7.csv"))
    names = ["บล็อกงานวิจัย (RCA 0%)", "ผลิตภัณฑ์ท้องตลาด ร้าน A", "ผลิตภัณฑ์ท้องตลาด ร้าน B"]
    rows = []
    for nm, r in zip(names, mk.itertuples()):
        v = np.array([r.s1, r.s2, r.s3]); rows.append([nm, f"{r.s1:.2f}", f"{r.s2:.2f}", f"{r.s3:.2f}", f"{r.mean_reported:.2f}", f"{v.std(ddof=1):.2f}", "ผ่าน" if v.min() >= TIS827_MPa else ("ไม่ผ่าน" if v.mean() < TIS827_MPa else "ค่าเฉลี่ยผ่าน แต่มีก้อนต่ำกว่าเกณฑ์")])
    b.table("rmkt", "การเปรียบเทียบกำลังอัด (MPa) ที่อายุ 28 วัน กับผลิตภัณฑ์คอนกรีตบล็อกปูพื้นในท้องตลาด", ["ตัวอย่าง", "ก้อนที่ 1", "ก้อนที่ 2", "ก้อนที่ 3", "เฉลี่ย", "SD", "เทียบเกณฑ์ 35 MPa"], rows, [2400, 1000, 1000, 1000, 1000, 900, 2100], align=["left"] + ["center"] * 6, sz=20,
            note="หมายเหตุ เกณฑ์ มอก. 827-2565 กำหนดค่าไม่ต่ำกว่า 35 MPa ตามที่ระบุในร่างเดิม ค่าเฉลี่ยของบล็อกงานวิจัยในตารางนี้ (55.42) ต่างจาก{tab:rfc2} (55.43) 0.01 MPa เพราะการปัดเศษ")
    b.fig("rmkt", fp("r_market_shape"), 15.0, "(ก) กำลังอัดที่ 28 วันของบล็อกงานวิจัยเทียบกับผลิตภัณฑ์จากสองร้าน จุดคือค่ารายก้อน แถบคือ ±1 SD (ข) กำลังอัดของชิ้นทรงลูกบาศก์และบล็อกปูพื้นที่ใช้อัตราส่วนผสมเดียวกัน ตัวเลข × คืออัตราส่วนบล็อกต่อลูกบาศก์ ผู้วิจัยสร้างภาพจาก{tab:rmkt} และ{tab:rshape}")
    b.p(f"บล็อกงานวิจัยมีกำลังอัดเฉลี่ย {f2(N['mk_this'])} MPa ส่วนผลิตภัณฑ์จากร้าน A และ B เฉลี่ย {f2(N['mk_A'])} และ {f2(N['mk_B'])} MPa ตามลำดับ หรือเป็น {N['mk_this']/N['mk_A']:.1f} และ {N['mk_this']/N['mk_B']:.1f} เท่า ทั้งสามก้อนของผลิตภัณฑ์ทั้งสองร้านต่ำกว่า 35 MPa ร่างเดิมสรุปว่าผลิตภัณฑ์ท้องตลาดทั้งสองแหล่งต่ำกว่าเกณฑ์ ข้อความนี้ถูกต้องในแง่ค่าเฉลี่ย แต่ผู้วิจัยปรับถ้อยคำให้ชัดว่าเป็นผลเฉพาะตัวอย่างที่ทดสอบ")
    b.p(ot(362).replace("(ข้อจำกัดที่ผู้วิจัยระบุไว้)", "และร่างเดิมไม่ระบุอายุ รุ่นการผลิต หรือขนาดของตัวอย่างที่ซื้อมา (ข้อจำกัดที่ผู้วิจัยระบุไว้)"))
    b.h3("4.6.2 อิทธิพลของรูปทรงชิ้นทดสอบต่อกำลังอัดที่วัดได้")
    b.p("ร่างเดิมสรุปในหัวข้อสรุปผลว่าบล็อกปูพื้นรูปคดกริชให้กำลังอัดสูงกว่าชิ้นทรงลูกบาศก์ที่ใช้ส่วนผสมเดียวกันร้อยละ 18 ถึง 49 แต่ตัวเลขนั้นไม่มีตารางหรือหัวข้อรองรับในเนื้อหาบทที่ 4 ผู้วิจัยจึงนำข้อมูลรายก้อนจากภาคผนวก ก-3 มาคำนวณและแสดงใน{tab:rshape}")
    rows = []
    for mix, key in (("RCA 0%", "RCA0"), ("RCA 10%", "RCA10")):
        c = pd.read_csv(os.path.join(DATA, "appendixA3_cube_per_specimen.csv")); c = c[c.mix == mix].strength_MPa
        rows.append([mix, f"{c.mean():.2f} ± {c.std(ddof=1):.2f}", f"{N['fc28_'+key]:.2f}", f"{N['fc28_'+key]/c.mean():.2f}", f"{pct(N['fc28_'+key], c.mean()):+.0f}"])
    b.table("rshape", "กำลังอัดที่ 28 วันของชิ้นทรงลูกบาศก์เทียบกับบล็อกปูพื้นรูปคดกริช (MPa)", ["สูตร", "ลูกบาศก์ (เฉลี่ย ± SD)", "บล็อกปูพื้น (เฉลี่ย)", "อัตราส่วนบล็อก/ลูกบาศก์", "ผลต่าง (%)"], rows, [1500, 2300, 1900, 2100, 1100], sz=21,
            note="หมายเหตุ ข้อมูลลูกบาศก์มีเพียง 3 ก้อนต่อสูตรและไม่ระบุขนาดชิ้นทดสอบในร่างเดิม " + PH + " มวลก้อนละประมาณ 7.7 กก. สอดคล้องกับลูกบาศก์ขนาดราว 150 มม. ที่ความหนาแน่นราว 2,300 กก./ม.³ ซึ่งเป็นข้อสันนิษฐานของผู้วิจัย")
    b.p(f"อัตราส่วนบล็อกต่อลูกบาศก์คือ {N['shape0']:.2f} สำหรับ RCA 0% และ {N['shape10']:.2f} สำหรับ RCA 10% หรือสูงกว่าร้อยละ {pct(N['fc28_RCA0'], N['cube0']):.0f} และ {pct(N['fc28_RCA10'], N['cube10']):.0f} ตามลำดับ ซึ่งตรงกับช่วงร้อยละ 18–49 ที่ร่างเดิมสรุป ผลนี้สอดคล้องกับกลศาสตร์ของการทดสอบอัดสองประการ ประการแรก ชิ้นเตี้ยที่ความสูงเพียง 6 ซม. ถูกแผ่นกดจำกัดการขยายตัวด้านข้างที่ปลายมากกว่าชิ้นทรงลูกบาศก์ (platen restraint) ส่วนที่ถูกจำกัดแข็งแรงขึ้นและกำลังที่อ่านได้สูงขึ้น ประการที่สอง ชิ้นทดสอบทั้งสองมีสัดส่วนความสูงต่อความกว้างต่างกันและความแปรปรวนของการอัดแน่นต่างกัน อัตราส่วนยังต่างกันมากระหว่างสองสูตร ({N['shape0']:.2f} เทียบ {N['shape10']:.2f}) จากตัวอย่างเพียง 3 ก้อนต่อสูตร จึงไม่ควรใช้ตัวคูณคงที่แปลงค่าระหว่างรูปทรง ข้อสรุปที่ปลอดภัยคือกำลังอัดของบล็อกปูพื้นไม่ควรเทียบโดยตรงกับกำลังอัดทรงลูกบาศก์ของคอนกรีตโครงสร้าง และเมื่อเทียบกับงานอื่นต้องตรวจรูปทรงชิ้นทดสอบก่อนเสมอ ดังที่อภิปรายไว้ในหัวข้อ 2.5.3")
